契约:
{ "type":"sim", "engine":"dynamics1d", "params":[{"name":"标识符","label":"标签","min":0,"max":2,"step":0.05,"default":0.9}], "model":{ "stateVar":"c","init":0.05,"steps":40,"update":"受限表达式：仅 params名/consts键/stateVar/噪声 xi/数学函数(sin cos tan exp log sqrt abs pow min max floor round PI E)。**不要**用 steps/init/target 等 model 字段(它们是配置不是表达式变量)。例 c + alpha*(T-c) + sigma*xi","consts":{"T":1} }, "regimes":[{"when":"受限布尔表达式如 alpha<1","label":"标签","desc":"说明","tone":"line|accent|ink(可选)"}], "chart":{"xLabel":"t","yLabel":"c(t)","targetLine":{"value":1,"label":"目标"}} }
  或 searchCompare(黑箱优化三策略): { "type":"sim","engine":"searchCompare","params":[{"name":"n","label":"预算 n =","min":5,"max":30,"step":1,"default":12,"decimals":0}],"model":{"objective":"受限表达式,变量只有 x,如 sin(x)+sin(10*x/3)","domain":[2.7,7.5],"yDomain":[-2.4,2.2],"strategies":["grid","random","bayes"],"budgetParam":"n"},"labels":{"grid":"网格","random":"随机","bayes":"贝叶斯"} }
  或 widget（把可动画演示的过程放进 sandbox iframe，适合排序/查找/图遍历/几何作图/运动——别硬塞进 dynamics1d）: { "type":"sim","engine":"widget","caption":"一句操作说明(可选)","html":"自包含片段：<style>…</style> + 控件(button/input range) + <canvas id=cv></canvas> + <script> 用 requestAnimationFrame 动画</script>" }
  widget 硬规则：零依赖纯 vanilla(canvas/SVG+原生 JS，禁 CDN/库)；颜色读主题 token——getComputedStyle(document.documentElement).getPropertyValue('--ink'|'--accent'|'--line'|'--bg')，禁写死色值；控件写片段内；禁 <!doctype>/<html>/<h1>、禁提示语胶囊(如 提示：)、禁 @media(prefers-color-scheme)。
  选引擎（防误用）：**真正的一维递推**——状态 x(t+1) 由 x(t) 演化，如收敛/发散/增长衰减/RSI/梯度下降——才用 dynamics1d；**别拿 dynamics1d 合成信号/傅里叶级数/多变量运动/二阶振子**（那不是一维一阶递推，写出来是貌似有数学其实错的伪仿真）：**尤其简谐振动/阻尼振子/单摆等二阶系统需位置 x 与速度 v 两个状态变量，而 dynamics1d 只有一个 stateVar——把速度塞进 consts 会被当字符串算出 NaN、图表全空白；这类改用 custom（computeJs 里自维护 x,v）或 widget（canvas 动画）**。这类可动画的信号/几何/运动/算法过程一律用 widget（canvas 动画）；一维黑箱优化→searchCompare；都不贴切就别放 sim（改用 flow/compare 讲清即可）。

本讲义课题: 「树（数据结构）」——本 block 所有内容必须紧扣此课题，标题/副题/示例严禁写成其它主题。所在页: 插入顺序决定树形。本 block 教学意图: dynamics1d 模拟：调整插入顺序，观察 BST 形状与高度从 log₂(n) 到 n-1 的变化。
只输出该 block 的 JSON。

response:
{
  "type": "sim",
  "engine": "widget",
  "caption": "拖动滑块调整插入顺序的偏度，观察树形与高度变化",
  "html": "<style>
  .bst-sim { font-family: sans-serif; padding: 10px; }
  .bst-controls { display: flex; flex-wrap: wrap; gap: 15px; align-items: center; margin-bottom: 15px; }
  .bst-control-group { display: flex; align-items: center; gap: 8px; }
  .bst-info { display: flex; gap: 20px; margin-top: 15px; font-size: 0.9em; }
  .bst-highlight { font-weight: bold; }
  #bst-cv { width: 100%; height: 350px; border-radius: 4px; }
  .bst-btn { padding: 4px 12px; border: 1px solid var(--line); background: transparent; color: var(--ink); border-radius: 4px; cursor: pointer; }
  .bst-btn:hover { background: var(--line); }
  input[type=range] { cursor: pointer; }
</style>
<div class="bst-sim">
  <div class="bst-controls">
    <div class="bst-control-group">
      <label>节点数 n = <span id="bst-n-val">10</span></label>
      <input type="range" id="bst-n-slider" min="3" max="25" step="1" value="10">
    </div>
    <div class="bst-control-group">
      <label>顺序度 = <span id="bst-skew-val">0.00</span></label>
      <input type="range" id="bst-skew-slider" min="0" max="1" step="0.05" value="0">
    </div>
    <button class="bst-btn" id="bst-build-btn">重建</button>
  </div>
  <canvas id="bst-cv"></canvas>
  <div class="bst-info">
    <span>当前高度: <span id="bst-h-val" class="bst-highlight">0</span></span>
    <span>理论下界 ⌊log₂n⌋: <span id="bst-min-h" class="bst-highlight">0</span></span>
    <span>最坏高度 n-1: <span id="bst-max-h" class="bst-highlight">0</span></span>
  </div>
</div>
<script>
  const cv = document.getElementById('bst-cv');
  const ctx = cv.getContext('2d');
  const nSlider = document.getElementById('bst-n-slider');
  const skewSlider = document.getElementById('bst-skew-slider');
  const nVal = document.getElementById('bst-n-val');
  const skewVal = document.getElementById('bst-skew-val');
  const hVal = document.getElementById('bst-h-val');
  const minH = document.getElementById('bst-min-h');
  const maxH = document.getElementById('bst-max-h');
  const buildBtn = document.getElementById('bst-build-btn');

  let root = null;
  let currentHeight = 0;

  function getThemeColor(varName) {
    return getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
  }

  function resizeCanvas() {
    const rect = cv.getBoundingClientRect();
    cv.width = rect.width * window.devicePixelRatio;
    cv.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  }

  class Node {
    constructor(val) {
      this.val = val;
      this.left = null;
      this.right = null;
      this.x = 0;
      this.y = 0;
    }
  }

  function insert(node, val) {
    if (!node) return new Node(val);
    if (val < node.val) node.left = insert(node.left, val);
    else node.right = insert(node.right, val);
    return node;
  }

  function getHeight(node) {
    if (!node) return 0;
    return 1 + Math.max(getHeight(node.left), getHeight(node.right));
  }

  function generateSequence(n, skew) {
    let available = [];
    for (let i = 1; i <= n; i++) available.push(i);
    let seq = [];
    for (let i = 0; i < n; i++) {
      let idx;
      if (Math.random() < skew) {
        idx = 0;
      } else {
        idx = Math.floor(Math.random() * available.length);
      }
      seq.push(available[idx]);
      available.splice(idx, 1);
    }
    return seq;
  }

  function layoutTree(node, depth, state) {
    if (!node) return;
    layoutTree(node.left, depth + 1, state);
    node.x = state.index++;
    node.y = depth;
    layoutTree(node.right, depth + 1, state);
  }

  function drawTree() {
    resizeCanvas();
    const w = cv.width / window.devicePixelRatio;
    const h = cv.height / window.devicePixelRatio;

    ctx.clearRect(0, 0, w, h);
    if (!root) return;

    const ink = getThemeColor('--ink');
    const accent = getThemeColor('--accent');
    const line = getThemeColor('--line');
    const bg = getThemeColor('--bg');

    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, w, h);

    let state = { index: 0 };
    layoutTree(root, 0, state);
    const totalNodes = state.index;
    const maxDepth = currentHeight - 1;

    const padding = 30;
    const xScale = (w - 2 * padding) / Math.max(1, totalNodes - 1);
    const yScale = (h - 2 * padding) / Math.max(1, maxDepth);

    function drawNode(node) {
      if (!node) return;
      const px = padding + node.x * xScale;
      const py = padding + node.y * yScale;

      if (node.left) {
        const cx = padding + node.left.x * xScale;
        const cy = padding + node.left.y * yScale;
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(cx, cy);
        ctx.strokeStyle = line;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }
      if (node.right) {
        const cx = padding + node.right.x * xScale;
        const cy = padding + node.right.y * yScale;
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(cx, cy);
        ctx.strokeStyle = line;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }

      drawNode(node.left);
      drawNode(node.right);

      const radius = Math.min(14, yScale / 2.5, xScale / 2.5);
      const fontSize = Math.max(8, Math.min(12, radius));

      ctx.beginPath();
      ctx.arc(px, py, radius, 0, Math.PI * 2);
      ctx.fillStyle = accent;
      ctx.fill();
      ctx.strokeStyle = ink;
      ctx.lineWidth = 1.5;
      ctx.stroke();

      ctx.fillStyle = ink;
      ctx.font = fontSize + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(node.val, px, py);
    }

    drawNode(root);
  }

  function build() {
    const n = parseInt(nSlider.value);
    const skew = parseFloat(skewSlider.value);

    nVal.textContent = n;
    skewVal.textContent = skew.toFixed(2);

    const seq = generateSequence(n, skew);
    root = null;
    for (const val of seq) {
      root = insert(root, val);
    }

    currentHeight = getHeight(root);
    hVal.textContent = currentHeight;
    minH.textContent = Math.floor(Math.log2(n));
    maxH.textContent = n - 1;

    drawTree();
  }

  nSlider.addEventListener('input', build);
  skewSlider.addEventListener('input', build);
  buildBtn.addEventListener('click', build);
  window.addEventListener('resize', drawTree);

  build();
</script>"
}
